 for item,folder in [(j['grammar'],'grammars'),(j['query'],'queries')]+[(s,'inputs') for s in j['sources']]:
  key='library' if folder=='grammars' else 'path';p=Path(item[key]);h=hashlib.sha256(p.read_bytes()).hexdigest();name=h+p.suffix;shutil.copy2(p,d/folder/name);item[key]=remote+'/'+folder+'/'+name
